package generator

import (
	"io/fs"
	"maps"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"sort"
	"strings"
	"testing"
)

// The vocabulary file's header. TestWebRuntimeVocabularyIsCurrent writes it.
const webRuntimeVocabularyHeader = `# webruntime_vocabulary.txt — the identifiers forge's GENERATED frontend code
# shares with @reliantlabs/forge-web-runtime's declarations: every token of a
# template (or Go-emitted golden) whose first line is "// Code generated by
# forge. DO NOT EDIT." that web-runtime/src (tests excluded) declares as an
# export, an interface/object member or a method.
#
# forge generate checks a frontend's installed runtime for each one its
# generated files use (WebRuntimeContentNotices). Never edit by hand:
#   UPDATE_WEBRUNTIME_VOCABULARY=1 go test -short -run TestWebRuntimeVocabularyIsCurrent ./internal/generator/
`

// webRuntimeVocabularyFile is the checked-in list, relative to this package.
const webRuntimeVocabularyFile = "webruntime_vocabulary.txt"

var (
	// An exported declaration: `export [declare] [default] [abstract] [async]
	// function|const|let|var|class|interface|type|enum NAME`.
	runtimeExportDeclRe = regexp.MustCompile(`(?m)^\s*export\s+(?:declare\s+)?(?:default\s+)?(?:abstract\s+)?(?:async\s+)?(?:function\*?|const|let|var|class|interface|type|enum)\s+([A-Za-z_$][\w$]*)`)
	// An export list: `export [type] { a, b as c }`.
	runtimeExportListRe = regexp.MustCompile(`export\s+(?:type\s+)?\{([^{}]*)\}`)
	// A member or method at the start of an indented line: `  name?: T`,
	// `  readonly name: T`, `  name(arg)`. Object-literal keys match too, which
	// is what an option bag passed to the runtime looks like at its use site.
	runtimeMemberRe = regexp.MustCompile(`(?m)^\s+(?:readonly\s+)?([A-Za-z_$][\w$]*)\??\s*[:(]`)
	// A Go template action, stripped before a template is tokenized.
	templateActionRe = regexp.MustCompile(`(?s)\{\{.*?\}\}`)
)

// tsKeywords never name a runtime feature, though runtimeMemberRe sees
// `if (`, `for (` and friends at the start of indented lines.
var tsKeywords = map[string]bool{
	"if": true, "for": true, "while": true, "switch": true, "catch": true, "return": true,
	"function": true, "new": true, "typeof": true, "await": true, "yield": true, "case": true,
	"default": true, "else": true, "do": true, "try": true, "finally": true, "throw": true,
	"get": true, "set": true, "async": true, "constructor": true, "super": true, "this": true,
	"import": true, "export": true, "void": true, "delete": true, "in": true, "of": true,
}

// runtimeDeclaredNames returns every name web-runtime/src declares in what it
// publishes: tsconfig.build.json leaves out tests and src/testdata.
func runtimeDeclaredNames(t *testing.T, srcDir string) map[string]bool {
	t.Helper()
	names := map[string]bool{}
	err := filepath.WalkDir(srcDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if d.Name() == "__tests__" || d.Name() == "testdata" || d.Name() == "node_modules" {
				return filepath.SkipDir
			}
			return nil
		}
		name := d.Name()
		if (!strings.HasSuffix(name, ".ts") && !strings.HasSuffix(name, ".tsx")) ||
			strings.Contains(name, ".test.") {
			return nil
		}
		body, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		text := stripTSProse(string(body))
		for _, m := range runtimeExportDeclRe.FindAllStringSubmatch(text, -1) {
			names[m[1]] = true
		}
		for _, m := range runtimeExportListRe.FindAllStringSubmatch(text, -1) {
			for _, clause := range strings.Split(m[1], ",") {
				for _, part := range strings.Fields(strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(clause), "type "))) {
					if part != "as" && tsIdentifierRe.MatchString(part) {
						names[part] = true
					}
				}
			}
		}
		for _, m := range runtimeMemberRe.FindAllStringSubmatch(text, -1) {
			names[m[1]] = true
		}
		return nil
	})
	if err != nil {
		t.Fatalf("walk %s: %v", srcDir, err)
	}
	for kw := range tsKeywords {
		delete(names, kw)
	}
	return names
}

// generatedTemplateTokens returns every identifier in forge's generated
// frontend output as the repository declares it: templates under
// internal/templates whose first line is the generated header (Go template
// actions stripped), and the goldens of Go-emitted TypeScript.
func generatedTemplateTokens(t *testing.T) map[string]bool {
	t.Helper()
	tokens := map[string]bool{}
	files := 0
	scan := func(root string, want func(name string) bool) {
		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() || !want(d.Name()) {
				return nil
			}
			body, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			if !strings.HasPrefix(string(body), generatedTSHeader) {
				return nil
			}
			files++
			addIdentifiers(tokens, stripTSProse(templateActionRe.ReplaceAllString(string(body), " ")))
			return nil
		})
		if err != nil {
			t.Fatalf("walk %s: %v", root, err)
		}
	}
	scan(filepath.Join("..", "templates"), func(name string) bool {
		return strings.HasSuffix(name, ".ts.tmpl") || strings.HasSuffix(name, ".tsx.tmpl") ||
			strings.HasSuffix(name, ".ts") || strings.HasSuffix(name, ".tsx")
	})
	scan(filepath.Join("testdata", "service_mocks"), func(name string) bool {
		return strings.HasSuffix(name, ".ts.golden")
	})
	if files < 10 {
		t.Fatalf("found only %d generated frontend templates; the scanner has drifted from the template layout and the vocabulary would be inert", files)
	}
	return tokens
}

func computeWebRuntimeVocabulary(t *testing.T) []string {
	t.Helper()
	declared := runtimeDeclaredNames(t, filepath.Join("..", "..", "web-runtime", "src"))
	var out []string
	for tok := range generatedTemplateTokens(t) {
		if declared[tok] {
			out = append(out, tok)
		}
	}
	sort.Strings(out)
	return out
}

// TestWebRuntimeVocabularyIsCurrent keeps the embedded vocabulary in step with
// the templates and the runtime source, so the content check forge generate
// runs can never be judging an old list. Hermetic: it reads both trees itself,
// which also keeps Go's test cache honest about them.
func TestWebRuntimeVocabularyIsCurrent(t *testing.T) {
	if _, err := os.Stat(filepath.Join("..", "..", "web-runtime", "src")); err != nil {
		t.Fatalf("web-runtime/src not readable: %v", err)
	}
	want := webRuntimeVocabularyHeader + strings.Join(computeWebRuntimeVocabulary(t), "\n") + "\n"
	if os.Getenv("UPDATE_WEBRUNTIME_VOCABULARY") != "" {
		if err := os.WriteFile(webRuntimeVocabularyFile, []byte(want), 0o644); err != nil {
			t.Fatal(err)
		}
		return
	}
	got, err := os.ReadFile(webRuntimeVocabularyFile)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != want {
		t.Fatalf("%s is stale: the generated templates or web-runtime/src changed what generated code shares with the runtime.\n"+
			"Regenerate it:\n  UPDATE_WEBRUNTIME_VOCABULARY=1 go test -short -run TestWebRuntimeVocabularyIsCurrent ./internal/generator/",
			webRuntimeVocabularyFile)
	}
	if string(got) != webRuntimeVocabularyText {
		t.Fatalf("the embedded vocabulary differs from %s on disk; rebuild", webRuntimeVocabularyFile)
	}
}

// The motivating case: otel_gen.ts passes initBrowserTelemetry's rpcForensics
// (forge#2348), which no runtime before it ships. And the imports generated
// code depends on (createMutationCall: 0.13.5) are in it too.
func TestWebRuntimeVocabularyCoversOptionsAndImports(t *testing.T) {
	vocab := webRuntimeVocabulary()
	for _, want := range []string{"rpcForensics", "initBrowserTelemetry", "createMutationCall", "createServiceMutations"} {
		if !vocab[want] {
			t.Errorf("vocabulary lacks %s", want)
		}
	}
	for kw := range tsKeywords {
		if vocab[kw] {
			t.Errorf("vocabulary carries the keyword %q", kw)
		}
	}
}

func installRuntime(t *testing.T, nodeModules, version string, shipped ...string) {
	t.Helper()
	dir := filepath.Join(nodeModules, filepath.FromSlash(WebRuntimePackage))
	writeFile(t, filepath.Join(dir, "package.json"), `{"name":"`+WebRuntimePackage+`","version":"`+version+`","exports":{"./telemetry":{"types":"./dist/telemetry.d.ts","default":"./dist/telemetry.js"},"./service-hooks":{"types":"./dist/service-hooks.d.ts","default":"./dist/service-hooks.js"}}}`)
	fields := ""
	if slices.Contains(shipped, "rpcForensics") {
		fields = "rpcForensics?: boolean;"
	}
	writeFile(t, filepath.Join(dir, "dist", "telemetry.d.ts"), "export interface BrowserTelemetryConfig {"+fields+"}\n"+
		"export declare function initBrowserTelemetry(options: BrowserTelemetryConfig): void;\n"+
		"export interface AnotherConfig { rpcForensics: boolean; }\n")
	writeFile(t, filepath.Join(dir, "dist", "telemetry.js"), `const rpcForensics = "rpcForensics";
export function initBrowserTelemetry(config) { return rpcForensics; }
export function createMutationCall() {}
`)
	writeFile(t, filepath.Join(dir, "dist", "service-hooks.d.ts"), "export declare function createQueryHook(): void;\n")
	writeFile(t, filepath.Join(dir, "dist", "service-hooks.js"), `function createMutationCall() {}
export function createQueryHook() { return createMutationCall; }
`)
}

func writeFile(t *testing.T, path, body string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
}

const otelGenFixture = generatedTSHeader + `
import { initBrowserTelemetry } from "@reliantlabs/forge-web-runtime/telemetry";
initBrowserTelemetry({
  rpcForensics: true,
});
`

func TestWebRuntimeContentNotices_NamesOptionsTheInstalledRuntimeLacks(t *testing.T) {
	project := t.TempDir()
	fe := filepath.Join("frontends", "web")
	writeFile(t, filepath.Join(project, fe, "src", "lib", "otel_gen.ts"), otelGenFixture)
	// The project's own file uses the option too; it is not forge's to judge.
	writeFile(t, filepath.Join(project, fe, "src", "lib", "mine.ts"), "export const o = { rpcForensics: true };\n")
	installRuntime(t, filepath.Join(project, fe, "node_modules"), "0.13.19", "initBrowserTelemetry")

	notices := WebRuntimeContentNotices(project, fe)
	if len(notices) != 1 {
		t.Fatalf("want one notice, got %q", notices)
	}
	n := notices[0]
	for _, want := range []string{"0.13.19", "rpcForensics (src/lib/otel_gen.ts)", "npm update " + WebRuntimePackage} {
		if !strings.Contains(n, want) {
			t.Errorf("notice lacks %q:\n%s", want, n)
		}
	}
	if strings.Contains(n, "mine.ts") || strings.Contains(n, "initBrowserTelemetry") {
		t.Errorf("notice names something the installed runtime ships, or a file forge does not own:\n%s", n)
	}
}

func TestWebRuntimeContentNotices_RequireTheImportedEntrypointExport(t *testing.T) {
	project := t.TempDir()
	fe := filepath.Join("frontends", "web")
	writeFile(t, filepath.Join(project, fe, "src", "hooks_gen.ts"), generatedTSHeader+`
import { createMutationCall as createCall, createQueryHook } from "@reliantlabs/forge-web-runtime/service-hooks";
export const result = [createCall, createQueryHook];
`)
	installRuntime(t, filepath.Join(project, fe, "node_modules"), "0.13.19")
	n := WebRuntimeContentNotices(project, fe)
	if len(n) != 1 || !strings.Contains(n[0], "createMutationCall (src/hooks_gen.ts)") || strings.Contains(n[0], "createQueryHook") {
		t.Fatalf("want only the missing export on its imported subpath; got %q", n)
	}
}

// A hook file that resolves its client from the query's scope (forge#2726)
// against a runtime from before /transport-scope existed: the entry point is
// absent from its exports map, so scopedClient is named, and nothing the
// runtime does ship is.
func TestWebRuntimeContentNotices_NameScopedClientOnARuntimeWithoutTransportScope(t *testing.T) {
	project := t.TempDir()
	fe := filepath.Join("frontends", "web")
	writeFile(t, filepath.Join(project, fe, "src", "hooks", "item-service-hooks_gen.ts"), generatedTSHeader+`
import { createQueryHook } from "@reliantlabs/forge-web-runtime/service-hooks";
import { scopedClient } from "@reliantlabs/forge-web-runtime/transport-scope";
export const result = [createQueryHook, scopedClient];
`)
	installRuntime(t, filepath.Join(project, fe, "node_modules"), "0.13.21")
	n := WebRuntimeContentNotices(project, fe)
	if len(n) != 1 || !strings.Contains(n[0], "scopedClient (src/hooks/item-service-hooks_gen.ts)") || strings.Contains(n[0], "createQueryHook") {
		t.Fatalf("want a notice naming only scopedClient; got %q", n)
	}
}

func TestWebRuntimeContentNotices_SilentWhenShippedOrNotJudgeable(t *testing.T) {
	fe := filepath.Join("frontends", "web")
	t.Run("ships everything, hoisted to the project root", func(t *testing.T) {
		project := t.TempDir()
		writeFile(t, filepath.Join(project, fe, "src", "lib", "otel_gen.ts"), otelGenFixture)
		installRuntime(t, filepath.Join(project, "node_modules"), "0.13.20", "initBrowserTelemetry", "rpcForensics")
		if n := WebRuntimeContentNotices(project, fe); n != nil {
			t.Fatalf("want no notice, got %q", n)
		}
	})
	t.Run("not installed", func(t *testing.T) {
		project := t.TempDir()
		writeFile(t, filepath.Join(project, fe, "src", "lib", "otel_gen.ts"), otelGenFixture)
		if n := WebRuntimeContentNotices(project, fe); n != nil {
			t.Fatalf("want no notice, got %q", n)
		}
	})
	t.Run("installed without compiled output", func(t *testing.T) {
		project := t.TempDir()
		writeFile(t, filepath.Join(project, fe, "src", "lib", "otel_gen.ts"), otelGenFixture)
		writeFile(t, filepath.Join(project, fe, "node_modules", filepath.FromSlash(WebRuntimePackage), "package.json"), `{"version":"0.13.19"}`)
		if n := WebRuntimeContentNotices(project, fe); n != nil {
			t.Fatalf("want no notice, got %q", n)
		}
	})
	t.Run("bridged to a dev forge checkout", func(t *testing.T) {
		project := t.TempDir()
		writeFile(t, filepath.Join(project, fe, "src", "lib", "otel_gen.ts"), otelGenFixture)
		installRuntime(t, filepath.Join(project, fe, "node_modules"), "0.13.19")
		if err := os.MkdirAll(filepath.Join(project, devLinkDir, "web-runtime"), 0o755); err != nil {
			t.Fatal(err)
		}
		if n := WebRuntimeContentNotices(project, fe); n != nil {
			t.Fatalf("want no notice, got %q", n)
		}
	})
}

func TestWebRuntimeContentNotices_PnpmLockNamesPnpm(t *testing.T) {
	project := t.TempDir()
	fe := filepath.Join("frontends", "web")
	writeFile(t, filepath.Join(project, fe, "package.json"), `{"name":"web"}`)
	writeFile(t, filepath.Join(project, fe, "pnpm-lock.yaml"), "lockfileVersion: '9.0'\n")
	writeFile(t, filepath.Join(project, fe, "src", "lib", "otel_gen.ts"), otelGenFixture)
	installRuntime(t, filepath.Join(project, fe, "node_modules"), "0.13.19", "initBrowserTelemetry")
	n := WebRuntimeContentNotices(project, fe)
	if len(n) != 1 || !strings.Contains(n[0], "pnpm update "+WebRuntimePackage) {
		t.Fatalf("want a pnpm update hint, got %q", n)
	}
}

func TestFunctionOptionMembers_NewlineSeparatedMembers(t *testing.T) {
	text := "export interface BrowserTelemetryConfig {\n" +
		"  endpoint: string\n" +
		"  readonly level?:\n" +
		"    | \"debug\"\n" +
		"    | \"info\"\n" +
		"  nested: { inner: boolean; other: number }\n" +
		"  rpcForensics?: boolean\n" +
		"}\n" +
		"export declare function initBrowserTelemetry(options: BrowserTelemetryConfig): void;\n"
	got, ok := functionOptionMembers(text, "initBrowserTelemetry")
	if !ok {
		t.Fatal("a newline-separated interface was not judged")
	}
	want := map[string]bool{"endpoint": true, "level": true, "nested": true, "rpcForensics": true}
	if !maps.Equal(got, want) {
		t.Errorf("members = %v, want %v", got, want)
	}
}
